SELECT rowid AS history_rowid, * FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

SELECT rowid AS history_rowid, * FROM transactions INDEXED BY idx_transactions_date
         WHERE 1 = 1 AND substr(date, 1, ?) = ? AND (account_id = ? OR (type <> 'internalTransfer' AND target_account_id = ?)) AND category_id = ? 
         ORDER BY date DESC, created_at DESC, rowid DESC LIMIT ?;

